        "b": ["x", "y", "z"]
    })

    df3 = pl.DataFrame({
        "a": [1, 2, 4],
        "b": ["x", "y", "z"]
    })

    df4 = pl.DataFrame({
        "a": [1, 2, 3],
        "b": ["x", "y", "z"],
        "c": [1.0, 2.0, 3.0]
    })

